#include <bits/stdc++.h>
using namespace std;

class Solution {
public:
    bool threeConsecutiveOdds(vector<int>& arr) {
        int run = 0;
        for (int x : arr) {
            run = (x % 2 != 0) ? run + 1 : 0;
            if (run == 3) return true;
        }
        return false;
    }
};
